import numpy as np
def _form(q, n):
    x = np.arange(n, dtype=float)
    w = q ** (0.5 * x)
    return 0.5 * np.sign(x[None, :] - x[:, None]) * np.outer(w, w)
def _generic(n, seed):
    a = np.random.default_rng(seed).normal(size=(n, n))
    return a - a.T
def _pairs(G, raw):
    cols = []
    for r in raw.T:
        v = np.array(r, dtype=float)
        for k in range(len(cols) // 2):
            a, b = cols[2 * k], cols[2 * k + 1]
            v = v + (b @ G @ v) * a - (a @ G @ v) * b
        if len(cols) % 2:
            v = v / (cols[-1] @ G @ v)
        cols.append(v)
    return np.array(cols).T.reshape(G.shape[0], len(cols))
def _red(out):
    v, h = out
    v = np.asarray(v, dtype=float)
    h = np.asarray(h, dtype=float)
    k = np.arange(v.size)
    j = np.arange(h.size)
    return float(np.sum(v * np.cos(0.7 * k)) + 3.0 * np.sum(h * np.sin(1.3 * j + 0.2))
                 + 10.0 * v.size + 100.0 * h.size)
rng = np.random.default_rng(5)
raw = rng.normal(size=(10, 6))
G = _form(0.4, 10)
B = _pairs(G, raw[:, :2])
v0 = raw[:, 2].copy()
import copy
def _preserved(fn, *args, **kwargs):
    saved_args = copy.deepcopy(args)
    saved_kwargs = copy.deepcopy(kwargs)
    result = fn(*args, **kwargs)
    for actual, before in list(zip(args, saved_args)) + [(kwargs[k], saved_kwargs[k]) for k in kwargs]:
        if isinstance(actual, np.ndarray):
            assert np.array_equal(actual, before, equal_nan=True), 'Array input was modified'
        else:
            assert actual == before, 'Input was modified'
    return result
assert np.allclose(_red(_preserved(skew_orthonormalize, B.copy(), v0.copy(), G.copy())), target)

